SET NOCOUNT ON;
SET LOCK_TIMEOUT 15000;

SELECT 'Chefz core migration' CheckName, IIF(EXISTS(SELECT 1 FROM migration.__ApplicationMigrationsHistory WHERE MigrationId='20261010112122_AddChefzAccountsSettlementsAndPerformance'),1,0) Passed
UNION ALL SELECT 'Chefz reports migration', IIF(EXISTS(SELECT 1 FROM migration.__ApplicationMigrationsHistory WHERE MigrationId='20261011191524_AddChefzWorkbookReportsAndStatistics'),1,0)
UNION ALL SELECT 'Chefz money import migration', IIF(EXISTS(SELECT 1 FROM migration.__ApplicationMigrationsHistory WHERE MigrationId='20261012093719_AddChefzOrderSettlementImports'),1,0)
UNION ALL SELECT 'Chefz permission migration', IIF(EXISTS(SELECT 1 FROM migration.__IdentityMigrationsHistory WHERE MigrationId='20261010112140_GrantChefzPermissions'),1,0)
UNION ALL SELECT 'Account rowversion', IIF(EXISTS(SELECT 1 FROM sys.columns WHERE object_id=OBJECT_ID(N'app.PlatformRiderAccounts') AND name='RowVersion' AND TYPE_NAME(system_type_id)='timestamp'),1,0)
UNION ALL SELECT 'Assignment slots column', IIF(COL_LENGTH(N'app.RiderClientAssignments',N'RiderAccountSlot') IS NOT NULL,1,0)
UNION ALL SELECT 'Slots one and two constraint', IIF(EXISTS(SELECT 1 FROM sys.check_constraints WHERE parent_object_id=OBJECT_ID(N'app.RiderClientAssignments') AND name='CK_RiderClientAssignments_RiderAccountSlot' AND is_disabled=0 AND is_not_trusted=0),1,0)
UNION ALL SELECT 'No unique rider-only index', IIF(NOT EXISTS(SELECT 1 FROM sys.indexes i WHERE i.object_id=OBJECT_ID(N'app.RiderClientAssignments') AND i.is_unique=1 AND i.is_disabled=0 AND (SELECT COUNT(*) FROM sys.index_columns c WHERE c.object_id=i.object_id AND c.index_id=i.index_id AND c.key_ordinal>0)=1 AND EXISTS(SELECT 1 FROM sys.index_columns c JOIN sys.columns col ON col.object_id=c.object_id AND col.column_id=c.column_id WHERE c.object_id=i.object_id AND c.index_id=i.index_id AND c.key_ordinal=1 AND col.name='RiderProfileId')),1,0)
UNION ALL SELECT 'Unique active rider slots', IIF(EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'app.RiderClientAssignments') AND name='IX_RiderClientAssignments_RiderProfileId_RiderAccountSlot' AND is_unique=1 AND is_disabled=0 AND has_filter=1),1,0)
UNION ALL SELECT 'Unique active account', IIF(EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'app.RiderClientAssignments') AND name='IX_RiderClientAssignments_PlatformRiderAccountId' AND is_unique=1 AND is_disabled=0 AND has_filter=1),1,0)
UNION ALL SELECT 'One salary account constraint', IIF(EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'app.RiderClientAssignments') AND name='IX_RiderClientAssignments_RiderProfileId_PaymentModel' AND is_unique=1 AND is_disabled=0 AND has_filter=1),1,0)
UNION ALL SELECT 'Unique report ID mapping', IIF(EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'chefz.AccountDetails') AND name='IX_AccountDetails_ReportIdNumber' AND is_unique=1 AND is_disabled=0),1,0)
UNION ALL SELECT 'Daily account-date uniqueness', IIF(EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'chefz.DailyPerformance') AND name='IX_DailyPerformance_PlatformRiderAccountId_ReportDate' AND is_unique=1 AND is_disabled=0),1,0)
UNION ALL SELECT 'Money assignment-period uniqueness', IIF(EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'chefz.WalletSettlements') AND name='IX_WalletSettlements_RiderClientAssignmentId_PeriodFrom' AND is_unique=1 AND is_disabled=0),1,0)
UNION ALL SELECT 'Money file hash uniqueness', IIF(EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'chefz.OrderSettlementImports') AND name='IX_OrderSettlementImports_ContentHash' AND is_unique=1 AND is_disabled=0),1,0)
UNION ALL SELECT 'Trusted money calculation constraint', IIF(EXISTS(SELECT 1 FROM sys.check_constraints WHERE parent_object_id=OBJECT_ID(N'chefz.WalletSettlements') AND name='CK_ChefzSettlement_Amounts' AND is_disabled=0 AND is_not_trusted=0),1,0)
UNION ALL SELECT 'Operational block dependency', IIF(OBJECT_ID(N'jahez.JahezTransferredDebt',N'U') IS NOT NULL,1,0)
UNION ALL SELECT 'Chefz permission definitions', IIF((SELECT COUNT(*) FROM platform.PermissionDefinitions WHERE [Key] IN ('chefz.read','chefz.accounts.update','chefz.performance.import','chefz.settlements.create') AND IsDeleted=0)=4,1,0)
UNION ALL SELECT 'System admin Chefz grants', IIF((SELECT COUNT(*) FROM [identity].RolePermissions WHERE RoleId='019c18d5-62e1-7000-9000-000000000001' AND PermissionKey IN ('chefz.read','chefz.accounts.update','chefz.performance.import','chefz.settlements.create') AND IsDeleted=0)=4,1,0);

SELECT name,is_unique,is_disabled,has_filter,filter_definition FROM sys.indexes WHERE object_id=OBJECT_ID(N'app.RiderClientAssignments') AND index_id>0 ORDER BY name;
SELECT name,definition,is_disabled,is_not_trusted FROM sys.check_constraints WHERE parent_object_id=OBJECT_ID(N'app.RiderClientAssignments') ORDER BY name;
SELECT MigrationId,ProductVersion FROM migration.__ApplicationMigrationsHistory WHERE MigrationId LIKE '%Chefz%' OR MigrationId='20261015072958_AddJahezWorkflowV2' ORDER BY MigrationId;
SELECT MigrationId,ProductVersion FROM migration.__IdentityMigrationsHistory WHERE MigrationId IN ('20261010112140_GrantChefzPermissions','20261015072948_GrantJahezWorkflowPermissions') ORDER BY MigrationId;
SELECT p.Id,p.Code,p.NameAr,COUNT_BIG(a.Id) NonDeletedAccounts FROM platform.ClientPlatforms p LEFT JOIN app.PlatformRiderAccounts a ON a.ClientPlatformId=p.Id AND a.IsDeleted=0 WHERE p.Code IN ('CHEFZ','THECHEFZ','CHEFSZ','SHIFTZ') AND p.IsDeleted=0 GROUP BY p.Id,p.Code,p.NameAr;
SELECT a.Status,COUNT_BIG(*) Accounts,COUNT_BIG(t.AccountId) Taken FROM app.PlatformRiderAccounts a JOIN platform.ClientPlatforms p ON p.Id=a.ClientPlatformId LEFT JOIN (SELECT DISTINCT PlatformRiderAccountId AccountId FROM app.RiderClientAssignments WHERE IsDeleted=0 AND EffectiveTo IS NULL) t ON t.AccountId=a.Id WHERE a.IsDeleted=0 AND p.IsDeleted=0 AND p.Code IN ('CHEFZ','THECHEFZ','CHEFSZ','SHIFTZ') GROUP BY a.Status ORDER BY a.Status;
SELECT x.AccountsPerRider,COUNT_BIG(*) Riders FROM (SELECT r.RiderProfileId,COUNT_BIG(*) AccountsPerRider FROM app.RiderClientAssignments r JOIN app.PlatformRiderAccounts a ON a.Id=r.PlatformRiderAccountId JOIN platform.ClientPlatforms p ON p.Id=a.ClientPlatformId WHERE r.IsDeleted=0 AND r.EffectiveTo IS NULL AND a.IsDeleted=0 AND p.IsDeleted=0 AND p.Code IN ('CHEFZ','THECHEFZ','CHEFSZ','SHIFTZ') GROUP BY r.RiderProfileId) x GROUP BY x.AccountsPerRider ORDER BY x.AccountsPerRider;
SELECT
 (SELECT COUNT_BIG(*) FROM (SELECT PlatformRiderAccountId FROM app.RiderClientAssignments WHERE IsDeleted=0 AND EffectiveTo IS NULL GROUP BY PlatformRiderAccountId HAVING COUNT_BIG(*)>1) q) DuplicateOpenAccountAssignments,
 (SELECT COUNT_BIG(*) FROM (SELECT RiderProfileId,RiderAccountSlot FROM app.RiderClientAssignments WHERE IsDeleted=0 AND EffectiveTo IS NULL GROUP BY RiderProfileId,RiderAccountSlot HAVING COUNT_BIG(*)>1) q) DuplicateOpenRiderSlots,
 (SELECT COUNT_BIG(*) FROM chefz.WalletSettlements WHERE RiderAmount<>GrossEarnings-CompanyAmount) InvalidSettlementArithmetic;
SELECT COUNT_BIG(*) Settlements,COALESCE(SUM(GrossEarnings),0) NetEarnings,COALESCE(SUM(CompanyAmount),0) CompanyAmount,COALESCE(SUM(RiderAmount),0) RiderAmount,(SELECT COUNT_BIG(*) FROM chefz.OrderSettlementImports) OrderImports FROM chefz.WalletSettlements;
SELECT COUNT_BIG(*) PerformanceRows,(SELECT COUNT_BIG(*) FROM chefz.PerformanceImports) PerformanceImports FROM chefz.DailyPerformance;
SELECT [Key],RequiresClientScope,IsDeleted FROM platform.PermissionDefinitions WHERE [Key] IN ('chefz.read','chefz.accounts.update','chefz.performance.import','chefz.settlements.create') ORDER BY [Key];
SELECT PermissionKey,IsDeleted FROM [identity].RolePermissions WHERE RoleId='019c18d5-62e1-7000-9000-000000000001' AND PermissionKey IN ('chefz.read','chefz.accounts.update','chefz.performance.import','chefz.settlements.create') ORDER BY PermissionKey;
SELECT SYSUTCDATETIME() VerifiedAtUtc;
